package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.compounding.*;
import dev.cosmerearcanists.feruchemy.*;
import dev.cosmerearcanists.nicrosil.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class CompoundingGameTests {
    private static FakePlayer player(GameTestHelper h,String metal){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"Compound"));p.setGameMode(GameType.SURVIVAL);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(1,8,1))));PowerAttributes.set(p,"a:"+metal,1);PowerAttributes.set(p,"f:"+metal,1);PowerData.reserve(p,metal,20);return p;}
    private static ItemStack ring(String metal){return new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,metal+"_metalmind_ring")));}
    private static ItemStack nugget(String metal){return new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,metal+"_nugget")));}
    private static void clean(FakePlayer p){TemporaryPowers.stop(p);CompoundingService.clear(p);NicrosilService.clear(p);SteelFeruchemy.clear(p);for(var stack:List.of(p.getMainHandItem(),p.getOffhandItem()))Metalminds.wipe(stack);}
    @GameTest(template="empty") public static void fillsOneEmptyMindFromReservesWithoutFeruchemicalStorageOrSeed(GameTestHelper h){var p=player(h,"steel");try{var mind=ring("steel");p.setItemInHand(InteractionHand.MAIN_HAND,mind);PowerData.state(p,"a:steel",-2);double before=PowerData.reserve(p,"steel");long tick=p.level().getGameTime();CompoundingService.tickAt(p,tick);double spent=before-PowerData.reserve(p,"steel");h.assertTrue(spent>0&&Math.abs(Metalminds.charge(mind)-spent*CompoundingConfig.GAIN.get())<1e-8,"Only Allomantic reserves fund the empty metalmind");h.assertTrue(PowerData.state(p,"f:steel")==0&&p.getOffhandItem().isEmpty(),"No Feruchemical state or offhand seed is required");h.assertTrue(PowerData.state(p,"a:steel")==0&&PowerData.controlState(p,"a:steel")==-2,"Ordinary Allomancy sees Off; selector sees Compounding");double after=Metalminds.charge(mind);CompoundingService.tickAt(p,tick);h.assertTrue(Metalminds.charge(mind)==after,"Same-tick callbacks cannot duplicate conversion");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void compoundingAndTappingOperateTogether(GameTestHelper h){var p=player(h,"steel");try{var mind=ring("steel");p.setItemInHand(InteractionHand.MAIN_HAND,mind);Metalminds.transfer(mind,p.getUUID(),"steel",10);PowerData.state(p,"f:steel",1);PowerData.state(p,"a:steel",-2);CompoundingService.tick(p);double filled=Metalminds.charge(mind);SteelFeruchemy.tick(p);h.assertTrue(filled>10&&Metalminds.charge(mind)<filled&&PowerData.state(p,"f:steel")==1,"Conversion adds charge while ordinary tapping consumes charge independently");h.assertTrue(p.getAttributeValue(Attributes.MOVEMENT_SPEED)>p.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue(),"The tapped speed effect still operates");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void fullMissingAndDisabledMetalmindsSpendNoReserves(GameTestHelper h){var p=player(h,"gold");boolean enabled=CompoundingConfig.ENABLED.get();try{PowerData.state(p,"a:gold",-2);double before=PowerData.reserve(p,"gold");long tick=p.level().getGameTime();CompoundingService.tickAt(p,tick);h.assertTrue(PowerData.reserve(p,"gold")==before,"Missing metalmind pauses conversion");var mind=ring("gold");p.setItemInHand(InteractionHand.MAIN_HAND,mind);Metalminds.transfer(mind,p.getUUID(),"gold",Metalminds.capacity(mind));CompoundingService.tickAt(p,tick+1);h.assertTrue(PowerData.reserve(p,"gold")==before,"Full metalmind pauses conversion");Metalminds.wipe(mind);CompoundingConfig.ENABLED.set(false);CompoundingService.tickAt(p,tick+2);h.assertTrue(PowerData.reserve(p,"gold")==before&&Metalminds.charge(mind)==0,"Disabled feature preserves fuel and items");}finally{CompoundingConfig.ENABLED.set(enabled);clean(p);}h.succeed();}
    @GameTest(template="empty") public static void vanillaAndModNuggetsAreEdibleAndChargedNuggetFillsReserves(GameTestHelper h){var p=player(h,"steel");try{var item=nugget("steel");p.setItemInHand(InteractionHand.MAIN_HAND,item);Metalminds.transfer(item,p.getUUID(),"steel",Metalminds.capacity(item));float health=p.getHealth();h.assertTrue(new ItemStack(Items.IRON_NUGGET).getUseDuration(p)==32&&new ItemStack(Items.GOLD_NUGGET).getUseAnimation()==UseAnim.EAT,"Vanilla nuggets use the same edible integration");h.assertTrue(item.getUseDuration(p)==32&&!CompoundingService.nugget(new ItemStack(Items.IRON_INGOT)),"Only nuggets are edible");item.finishUsingItem(h.getLevel(),p);h.assertTrue(item.isEmpty()&&PowerData.reserve(p,"steel")==PowerConfig.RESERVE_CAP.get(),"Eating consumes the nugget and refills matching reserves to maximum");h.assertTrue(Math.abs(PowerAttributes.strength(p,"a:steel")-1.5)<1e-8&&PowerAttributes.baseStrength(p,"a:steel")==1,"The full nugget gives +50% as a temporary modifier");h.assertTrue(Math.abs(health-p.getHealth()-2)<1e-5,"The unprotected consumer takes one heart of damage");long now=p.level().getGameTime();CompoundingService.updateBoostsAt(p,now+199);h.assertTrue(PowerAttributes.strength(p,"a:steel")>1,"The full boost lasts through tick199");CompoundingService.updateBoostsAt(p,now+200);h.assertTrue(PowerAttributes.strength(p,"a:steel")==1,"It expires at ten seconds");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void halfFullNuggetGivesHalfBoostAndDurationAndDoesNotStack(GameTestHelper h){var p=player(h,"steel");try{var full=nugget("steel");Metalminds.transfer(full,p.getUUID(),"steel",Metalminds.capacity(full));CompoundingService.eat(p,full);var half=nugget("steel");Metalminds.transfer(half,p.getUUID(),"steel",Metalminds.capacity(half)/2);PowerData.reserve(p,"steel",0);CompoundingService.eat(p,half);h.assertTrue(Math.abs(PowerAttributes.strength(p,"a:steel")-1.25)<1e-8&&PowerData.reserve(p,"steel")==PowerConfig.RESERVE_CAP.get(),"Re-eating replaces with +25%, does not stack, and still fully refills reserves");long now=p.level().getGameTime();CompoundingService.updateBoostsAt(p,now+99);h.assertTrue(PowerAttributes.strength(p,"a:steel")>1,"Half-full remains boosted before five seconds");CompoundingService.updateBoostsAt(p,now+100);h.assertTrue(PowerAttributes.strength(p,"a:steel")==1,"Half-full expires at five seconds");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void sourceIdentityAndForeignMetalmindRestrictionsCannotBeBypassed(GameTestHelper h){var p=player(h,"steel");try{PowerAttributes.set(p,"f:steel",0);PowerSources.grant(p,"f:steel",1,UUID.randomUUID());h.assertTrue(!CompoundingService.eligible(p,"steel"),"Different keyed power sources cannot compound");PowerSources.grant(p,"f:steel",.5,null);h.assertTrue(CompoundingService.eligible(p,"steel"),"A neutral acquired source is compatible with native Allomancy");var item=nugget("steel");Metalminds.transfer(item,UUID.randomUUID(),"steel",10);h.assertTrue(!CompoundingService.eat(p,item)&&item.getCount()==1&&Metalminds.charge(item)==10,"A foreign keyed charged nugget is preserved rather than eaten for compounding");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void nicrosilCompoundsSelectedTemporaryPowerWithoutRemovingPersonalPower(GameTestHelper h){var p=player(h,"nicrosil");try{PowerAttributes.set(p,"a:steel",1);var mind=ring("nicrosil");p.setItemInHand(InteractionHand.MAIN_HAND,mind);PowerData.state(p,"a:nicrosil",-2);var s=NicrosilService.open(p,mind);h.assertTrue(s!=null&&s.storing,"Negative Allomantic nicrosil opens the existing selection menu");NicrosilService.store(s,0,"a:steel");double before=PowerData.reserve(p,"nicrosil");CompoundingService.tick(p);var entry=NicrosilService.contents(p,mind).entries().getFirst();h.assertTrue(entry.kind()==NicrosilLedger.TEMPORARY&&entry.amount()==1&&PowerAttributes.baseStrength(p,"a:steel")==1,"Allomantic reserves produce temporary charge without transferring away permanent power");h.assertTrue(PowerData.reserve(p,"nicrosil")<before&&PowerData.state(p,"f:nicrosil")==0,"No Feruchemical storing mode is required");s.storing=false;NicrosilService.tap(s,entry.id());TemporaryPowers.tick(p);h.assertTrue(PowerAttributes.strength(p,"a:steel")>1&&PowerAttributes.baseStrength(p,"a:steel")==1,"Tapping the encoded output grants a paid modifier only");TemporaryPowers.stop(p);h.assertTrue(PowerAttributes.strength(p,"a:steel")==1,"Stopping temporary use restores personal strength");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void tinUsesSelectedSenseAndEatingNonNuggetsIsRejected(GameTestHelper h){var p=player(h,"tin");try{var item=ring("tin");p.setItemInHand(InteractionHand.MAIN_HAND,item);TinFeruchemy.sense(p,1);PowerData.state(p,"a:tin",-2);CompoundingService.tick(p);h.assertTrue(Metalminds.charge(item)>0&&Metalminds.storedMetal(item).equals("tin:hearing"),"Direct compounding stores the selected sense");h.assertTrue(!CompoundingService.eat(p,item)&&Metalminds.charge(item)>0,"Charged rings cannot be reverse compounded");}finally{clean(p);}h.succeed();}
    @GameTest(template="empty") public static void eatingChargedCopperNuggetErasesItsSharedNotebook(GameTestHelper h){var p=player(h,"copper");try{var item=nugget("copper");p.setItemInHand(InteractionHand.MAIN_HAND,item);PowerData.state(p,"f:copper",-1);var session=dev.cosmerearcanists.copper.CopperService.open(p,false);h.assertTrue(session!=null,"A nugget can hold a normal notebook");dev.cosmerearcanists.copper.CopperService.request(p,new dev.cosmerearcanists.copper.CopperNetwork.Request(dev.cosmerearcanists.copper.CopperNetwork.SAVE,session.token,dev.cosmerearcanists.copper.CopperNetwork.ZERO,"Memory","Erase this when eaten",0,new byte[0]));UUID id=dev.cosmerearcanists.copper.CopperService.identity(item);h.assertTrue(dev.cosmerearcanists.copper.CopperBooks.get(p.server).books.containsKey(id),"Fixture has a server notebook");h.assertTrue(CompoundingService.eat(p,item)&&!dev.cosmerearcanists.copper.CopperBooks.get(p.server).books.containsKey(id),"Consuming the charged nugget erases server notebook data");}finally{dev.cosmerearcanists.copper.CopperService.clear(p);clean(p);}h.succeed();}

}
